import { useState } from 'react';

function Counter() {
  const [count, setCount] = useState(0);

  function addTwo() {
    setCount(current => current + 1);
    setCount(current => current + 1);
  }

  return <button onClick={addTwo}>Giá trị: {count}</button>;
}

