function Accordion() {
  const [activeId, setActiveId] = useState<string | null>(null);

  return sections.map(section => (
    <Panel
      key={section.id}
      title={section.title}
      isOpen={activeId === section.id}
      onOpen={() => setActiveId(section.id)}
    />
  ));
